import XCTest
import SwiftData
@testable import TrainingOS

/// Stage 4F: proves `ConcurrentScheduler` places already-materialized
/// Sessions onto a tactical window per the kickoff's explicit contract —
/// hard vs. soft constraints, interference avoidance, double-session
/// pairing, recovery spacing, determinism, and impossible-mix handling
/// via `ScheduleProposal.conflicts` rather than silent dropping. These
/// are placement-algorithm tests: every `Session` here is a bare
/// pre-existing fixture, never generated by a `ProgrammingSystem` —
/// `ConcurrentScheduler` never looks past what it's handed.
@MainActor
final class ConcurrentSchedulerTests: XCTestCase {
    var container: ModelContainer!
    var context: ModelContext!

    override func setUpWithError() throws {
        container = PersistenceController.makeInMemoryContainer()
        context = container.mainContext
    }

    private func freshContext() -> ModelContext {
        ModelContext(container)
    }

    /// 2026-01-05 is a Monday — window offset 0 = Monday, offset 6 = Sunday,
    /// exactly matching `Weekday`'s own Monday-first ordering, so tests can
    /// reason about offsets and weekdays interchangeably.
    private func mondayStart() -> Date {
        Calendar.current.date(from: DateComponents(year: 2026, month: 1, day: 5))!
    }

    private func makeSession(
        _ name: String,
        modality: TrainingModality = .strength,
        stress: TrainingStressProfile? = nil
    ) -> Session {
        let session = Session(name: name, modality: modality)
        context.insert(session)
        if let stress {
            let block = WorkoutBlock(type: .strength, trainingStressProfile: stress)
            context.insert(block)
            session.addBlock(block)
        }
        return session
    }

    private func makeComponent(
        label: String,
        priority: GoalPriority,
        frequency: SessionFrequency,
        flexibility: ComponentFlexibility = .preferred,
        allowsDoubleSessionPairing: Bool = true,
        preferredDays: [Weekday] = [],
        requiredSpacingDays: Int? = nil,
        mix: TrainingMix? = nil
    ) -> TrainingMixComponent {
        let component = TrainingMixComponent(
            label: label,
            priority: priority,
            frequency: frequency,
            flexibility: flexibility,
            allowsDoubleSessionPairing: allowsDoubleSessionPairing,
            preferredDays: preferredDays,
            requiredSpacingDays: requiredSpacingDays
        )
        context.insert(component)
        mix?.addComponent(component)
        return component
    }

    private func heavy(_ modality: ActivityType? = nil) -> TrainingStressProfile {
        TrainingStressProfile(
            overallIntensity: .high, systemicDemand: .high, lowerBodyLoad: .high,
            upperBodyLoad: .low, impactLoading: .high, metabolicDemand: .moderate,
            durationClassification: .medium, modality: modality, recoveryDemand: .high
        )
    }

    private func light(_ modality: ActivityType? = nil) -> TrainingStressProfile {
        TrainingStressProfile(
            overallIntensity: .low, systemicDemand: .low, lowerBodyLoad: .low,
            upperBodyLoad: .none, impactLoading: .low, metabolicDemand: .low,
            durationClassification: .medium, modality: modality, recoveryDemand: .low
        )
    }

    // MARK: - Case B (REQUIRED): symmetric, modality-agnostic placement

    /// The kickoff's explicitly required proof: 3 Strength/Hypertrophy +
    /// 2 Functional Fitness + 1 Running across 6 days. This proves the
    /// scheduler is symmetric — the same `schedule()` call handles all
    /// three systems by construction, with no modality-specific branching
    /// anywhere in `ConcurrentScheduler`.
    func testCaseB_ThreeStrengthTwoFunctionalFitnessOneRunning_AcrossSixDays() throws {
        let mix = TrainingMix(kind: .selected, name: "Case B Hybrid")
        context.insert(mix)

        let strengthComponent = makeComponent(
            label: "Strength", priority: .primary,
            frequency: SessionFrequency(target: 3), mix: mix
        )
        let ffComponent = makeComponent(
            label: "Functional Fitness", priority: .secondary,
            frequency: SessionFrequency(target: 2), mix: mix
        )
        let runningComponent = makeComponent(
            label: "Running", priority: .supporting,
            frequency: SessionFrequency(target: 1), mix: mix
        )

        let strengthSessions = (0..<3).map { makeSession("Strength \($0)", modality: .strength) }
        let ffSessions = (0..<2).map { makeSession("FF \($0)", modality: .functionalFitness) }
        let runningSessions = [makeSession("Long Run", modality: .conditioning)]

        let inputs = [
            ScheduledProgramInput(component: strengthComponent, sessions: strengthSessions),
            ScheduledProgramInput(component: ffComponent, sessions: ffSessions),
            ScheduledProgramInput(component: runningComponent, sessions: runningSessions),
        ]

        let availability = UserAvailability(
            trainingDaysPerWeek: 6,
            unavailableWeekdays: [.sunday],
            allowsDoubleSessions: false,
            maxSessionsPerDay: 1
        )
        let constraints = SchedulingConstraints(
            availability: availability,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 6)
        )

        let proposal = ConcurrentScheduler.schedule(inputs, constraints: constraints)

        XCTAssertEqual(proposal.feasibility, .feasible)
        XCTAssertTrue(proposal.conflicts.isEmpty)
        XCTAssertEqual(proposal.placements.count, 6)

        // Every session got its own day (no doubles possible/needed: 6
        // sessions, 6 usable days).
        let uniqueDates = Set(proposal.placements.map(\.date))
        XCTAssertEqual(uniqueDates.count, 6)
        XCTAssertTrue(proposal.placements.allSatisfy { !$0.isDoubleSessionPairing })

        // Program order preserved within each component.
        let strengthDates = proposal.placements
            .filter { $0.componentLabel == "Strength" }
            .sorted { $0.date < $1.date }
        XCTAssertEqual(strengthDates.map(\.session.name), ["Strength 0", "Strength 1", "Strength 2"])

        // Symmetry: every placement carries `.programOrderPreserved`
        // regardless of which system produced it.
        XCTAssertTrue(proposal.placements.allSatisfy { $0.reasonCodes.contains(.programOrderPreserved) })
        // Primary-tier placements (Strength) are tagged accordingly.
        XCTAssertTrue(proposal.placements.filter { $0.componentLabel == "Strength" }.allSatisfy { $0.reasonCodes.contains(.primaryGoalPriority) })
        // This is the `.selected` mix — every placement should say so.
        XCTAssertTrue(proposal.placements.allSatisfy { $0.reasonCodes.contains(.userSelectedMix) })
    }

    // MARK: - Case A: double-session pairing prefers the lightest partner

    func testCaseA_HypertrophyPrimaryWithAerobicSecondary_DoublesPairWithLightestDays() throws {
        let mix = TrainingMix(kind: .recommended, name: "Case A Muscle Gain")
        context.insert(mix)

        let hypertrophyComponent = makeComponent(
            label: "Hypertrophy", priority: .primary,
            frequency: SessionFrequency(target: 5), mix: mix
        )
        let aerobicComponent = makeComponent(
            label: "Aerobic Base", priority: .secondary,
            frequency: SessionFrequency(target: 2), allowsDoubleSessionPairing: true, mix: mix
        )

        // Five weekday Hypertrophy sessions. The two `.high` days are kept
        // non-adjacent (Wed/Fri) so this fixture isolates double-session
        // pairing behavior without also triggering the primary
        // component's own adjacent-heavy-day interference avoidance —
        // that mechanism is proven separately by the Case C tests.
        let intensities: [LoadLevel] = [.low, .moderate, .high, .moderate, .high]
        let hypertrophySessions = intensities.enumerated().map { index, level in
            makeSession(
                "Hypertrophy \(index)",
                modality: .hypertrophy,
                stress: TrainingStressProfile(
                    overallIntensity: level, systemicDemand: level, lowerBodyLoad: level,
                    upperBodyLoad: level, impactLoading: .none, metabolicDemand: level,
                    durationClassification: .medium, modality: nil, recoveryDemand: level
                )
            )
        }
        let aerobicSessions = (0..<2).map { makeSession("Zone 2 \($0)", modality: .conditioning, stress: light(.running)) }

        let inputs = [
            ScheduledProgramInput(component: hypertrophyComponent, sessions: hypertrophySessions),
            ScheduledProgramInput(component: aerobicComponent, sessions: aerobicSessions),
        ]

        let availability = UserAvailability(
            trainingDaysPerWeek: 5,
            unavailableWeekdays: [.saturday, .sunday],
            allowsDoubleSessions: true,
            maxSessionsPerDay: 2
        )
        let constraints = SchedulingConstraints(
            availability: availability,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7)
        )

        let proposal = ConcurrentScheduler.schedule(inputs, constraints: constraints)

        XCTAssertEqual(proposal.feasibility, .feasible)
        XCTAssertEqual(proposal.placements.count, 7)

        let doubles = proposal.placements.filter { $0.isDoubleSessionPairing }
        XCTAssertEqual(doubles.count, 2)
        XCTAssertTrue(doubles.allSatisfy { $0.componentLabel == "Aerobic Base" })
        XCTAssertTrue(doubles.allSatisfy { $0.reasonCodes.contains(.doubleSessionSelected) })
        XCTAssertTrue(doubles.allSatisfy { $0.reasonCodes.contains(.lowIntensityPairing) })

        // The two doubles must land on the two LIGHTEST Hypertrophy days
        // (index 0 = .low, and one of the two .moderate days) — never on
        // the two .high days, since lighter partners were always
        // available.
        let doubleDates = Set(doubles.map(\.date))
        let hypertrophyByDate = Dictionary(uniqueKeysWithValues: proposal.placements
            .filter { $0.componentLabel == "Hypertrophy" }
            .map { ($0.date, $0.session.name) })
        let pairedHypertrophyNames = Set(doubleDates.compactMap { hypertrophyByDate[$0] })
        XCTAssertEqual(pairedHypertrophyNames, ["Hypertrophy 0", "Hypertrophy 1"])
    }

    // MARK: - Case C: interference avoidance

    func testCaseC_InterferenceAvoidedWhenANonAdjacentDayExists() throws {
        let mix = TrainingMix(kind: .selected, name: "Case C Functional Fitness Primary")
        context.insert(mix)

        let ffComponent = makeComponent(
            label: "Functional Fitness", priority: .primary,
            frequency: SessionFrequency(target: 1), mix: mix
        )
        let strengthComponent = makeComponent(
            label: "Strength", priority: .secondary,
            frequency: SessionFrequency(target: 1), mix: mix
        )

        let ffSession = makeSession("Heavy FF", modality: .functionalFitness, stress: heavy())
        let strengthSession = makeSession("Heavy Squat Day", modality: .strength, stress: heavy())

        let inputs = [
            ScheduledProgramInput(component: ffComponent, sessions: [ffSession]),
            ScheduledProgramInput(component: strengthComponent, sessions: [strengthSession]),
        ]

        // A 3-day window gives the second (lower-priority) session a
        // non-adjacent alternative (offset 2) to the primary's day
        // (offset 0) — the soft interference rule should steer it there.
        let availability = UserAvailability(trainingDaysPerWeek: 3, allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(
            availability: availability,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 3)
        )

        let proposal = ConcurrentScheduler.schedule(inputs, constraints: constraints)

        XCTAssertEqual(proposal.feasibility, .feasible)
        let ffPlacement = try XCTUnwrap(proposal.placements.first { $0.componentLabel == "Functional Fitness" })
        let strengthPlacement = try XCTUnwrap(proposal.placements.first { $0.componentLabel == "Strength" })

        XCTAssertEqual(ffPlacement.date, mondayStart())
        // Non-adjacent to the FF day (offset 0) means offset 2, not offset 1.
        XCTAssertEqual(strengthPlacement.date, Calendar.current.date(byAdding: .day, value: 2, to: mondayStart()))
        XCTAssertTrue(strengthPlacement.reasonCodes.contains(.interferenceAvoided))
        XCTAssertFalse(strengthPlacement.reasonCodes.contains(.softConstraintViolated))
    }

    func testCaseC_InterferenceViolatedWhenNoAlternativeDayExists() throws {
        let mix = TrainingMix(kind: .selected, name: "Forced Adjacency")
        context.insert(mix)

        let ffComponent = makeComponent(label: "Functional Fitness", priority: .primary, frequency: SessionFrequency(target: 1), mix: mix)
        let strengthComponent = makeComponent(label: "Strength", priority: .secondary, frequency: SessionFrequency(target: 1), mix: mix)

        let ffSession = makeSession("Heavy FF", modality: .functionalFitness, stress: heavy())
        let strengthSession = makeSession("Heavy Squat Day", modality: .strength, stress: heavy())

        let inputs = [
            ScheduledProgramInput(component: ffComponent, sessions: [ffSession]),
            ScheduledProgramInput(component: strengthComponent, sessions: [strengthSession]),
        ]

        // Only a 2-day window — no non-adjacent day is possible at all.
        let availability = UserAvailability(trainingDaysPerWeek: 2, allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(
            availability: availability,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 2)
        )

        let proposal = ConcurrentScheduler.schedule(inputs, constraints: constraints)

        XCTAssertEqual(proposal.feasibility, .feasibleWithSoftViolations)
        XCTAssertTrue(proposal.conflicts.isEmpty, "the session was still placed — a soft violation, not a dropped session")
        let strengthPlacement = try XCTUnwrap(proposal.placements.first { $0.componentLabel == "Strength" })
        XCTAssertTrue(strengthPlacement.reasonCodes.contains(.softConstraintViolated))
        XCTAssertFalse(proposal.warnings.isEmpty)
    }

    // MARK: - Hard constraints

    func testUnavailableWeekdayIsNeverUsed() throws {
        let mix = TrainingMix(kind: .selected, name: "Mix")
        context.insert(mix)
        let component = makeComponent(label: "Strength", priority: .primary, frequency: SessionFrequency(target: 3), mix: mix)
        let sessions = (0..<3).map { makeSession("S\($0)") }

        let availability = UserAvailability(trainingDaysPerWeek: 7, unavailableWeekdays: [.tuesday, .thursday], allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7))

        let proposal = ConcurrentScheduler.schedule([ScheduledProgramInput(component: component, sessions: sessions)], constraints: constraints)

        let weekdaysUsed = Set(proposal.placements.map { Calendar.current.component(.weekday, from: $0.date) })
        // Tuesday = weekday 3, Thursday = weekday 5 in Calendar's own convention.
        XCTAssertFalse(weekdaysUsed.contains(3))
        XCTAssertFalse(weekdaysUsed.contains(5))
    }

    func testMaxSessionsPerDayIsNeverExceededEvenWithDoublesAllowed() throws {
        let mix = TrainingMix(kind: .selected, name: "Mix")
        context.insert(mix)
        let a = makeComponent(label: "A", priority: .primary, frequency: SessionFrequency(target: 1), mix: mix)
        let b = makeComponent(label: "B", priority: .secondary, frequency: SessionFrequency(target: 1), mix: mix)
        let c = makeComponent(label: "C", priority: .supporting, frequency: SessionFrequency(target: 1), mix: mix)

        let sessionA = makeSession("A0")
        let sessionB = makeSession("B0")
        let sessionC = makeSession("C0")

        // Only ONE usable day, but max 2 sessions/day — the third must
        // become a conflict, never a silent third occupant.
        let availability = UserAvailability(trainingDaysPerWeek: 1, availableWeekdays: [.monday], allowsDoubleSessions: true, maxSessionsPerDay: 2)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 1))

        let proposal = ConcurrentScheduler.schedule([
            ScheduledProgramInput(component: a, sessions: [sessionA]),
            ScheduledProgramInput(component: b, sessions: [sessionB]),
            ScheduledProgramInput(component: c, sessions: [sessionC]),
        ], constraints: constraints)

        XCTAssertEqual(proposal.placements.count, 2)
        XCTAssertEqual(proposal.feasibility, .infeasible)
        XCTAssertEqual(proposal.conflicts.count, 1)
        XCTAssertEqual(proposal.conflicts.first?.componentLabel, "C")
    }

    func testRequiredSpacingDaysIsEnforcedAsAHardConstraint() throws {
        let mix = TrainingMix(kind: .selected, name: "Mix")
        context.insert(mix)
        let component = makeComponent(
            label: "Intervals", priority: .primary,
            frequency: SessionFrequency(target: 2), requiredSpacingDays: 3, mix: mix
        )
        let sessions = (0..<2).map { makeSession("Interval \($0)") }

        let availability = UserAvailability(trainingDaysPerWeek: 7, allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7))

        let proposal = ConcurrentScheduler.schedule([ScheduledProgramInput(component: component, sessions: sessions)], constraints: constraints)

        XCTAssertEqual(proposal.placements.count, 2)
        let dates = proposal.placements.sorted { $0.date < $1.date }.map(\.date)
        let gap = Calendar.current.dateComponents([.day], from: dates[0], to: dates[1]).day ?? 0
        XCTAssertGreaterThanOrEqual(gap, 3)
        XCTAssertTrue(proposal.placements.last { $0.date == dates[1] }?.reasonCodes.contains(.recoverySpacing) ?? false)
    }

