    func testSoftConstraintViolatedWhenNoPreferredDayIsAvailableAtAll() throws {
        let mix = TrainingMix(kind: .selected, name: "Mix")
        context.insert(mix)
        let component = makeComponent(
            label: "Strength", priority: .primary,
            frequency: SessionFrequency(target: 1), preferredDays: [.wednesday], mix: mix
        )
        let session = makeSession("S0")

        let availability = UserAvailability(trainingDaysPerWeek: 6, unavailableWeekdays: [.wednesday], allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7))

        let proposal = ConcurrentScheduler.schedule([ScheduledProgramInput(component: component, sessions: [session])], constraints: constraints)

        let placement = try XCTUnwrap(proposal.placements.first)
