    // MARK: - User-selected vs recommended

    func testUserSelectedMixReasonCodeOnlyAppliesToTheSelectedMix() throws {
        let selectedMix = TrainingMix(kind: .selected, name: "Selected")
        context.insert(selectedMix)
        let recommendedMix = TrainingMix(kind: .recommended, name: "Recommended")
        context.insert(recommendedMix)

        let selectedComponent = makeComponent(label: "Selected Strength", priority: .primary, frequency: SessionFrequency(target: 1), mix: selectedMix)
        let recommendedComponent = makeComponent(label: "Recommended Strength", priority: .primary, frequency: SessionFrequency(target: 1), mix: recommendedMix)

        let availability = UserAvailability(trainingDaysPerWeek: 7, allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 2))

        let selectedProposal = ConcurrentScheduler.schedule(
            [ScheduledProgramInput(component: selectedComponent, sessions: [makeSession("S")])],
            constraints: constraints
        )
        let recommendedProposal = ConcurrentScheduler.schedule(
            [ScheduledProgramInput(component: recommendedComponent, sessions: [makeSession("R")])],
            constraints: constraints
        )

        XCTAssertTrue(selectedProposal.placements.allSatisfy { $0.reasonCodes.contains(.userSelectedMix) })
        XCTAssertTrue(recommendedProposal.placements.allSatisfy { !$0.reasonCodes.contains(.userSelectedMix) })
    }

    // MARK: - Determinism

    func testIdenticallyShapedInputsAlwaysProduceTheSameSchedule() throws {
        func buildInputs() -> [ScheduledProgramInput] {
            let mix = TrainingMix(kind: .selected, name: "Mix")
            context.insert(mix)
            let strength = makeComponent(label: "Strength", priority: .primary, frequency: SessionFrequency(target: 3), mix: mix)
            let ff = makeComponent(label: "Functional Fitness", priority: .secondary, frequency: SessionFrequency(target: 2), mix: mix)
            let running = makeComponent(label: "Running", priority: .supporting, frequency: SessionFrequency(target: 1), mix: mix)
            return [
                ScheduledProgramInput(component: strength, sessions: (0..<3).map { makeSession("Strength \($0)") }),
                ScheduledProgramInput(component: ff, sessions: (0..<2).map { makeSession("FF \($0)", stress: heavy()) }),
                ScheduledProgramInput(component: running, sessions: [makeSession("Run", stress: light(.running))]),
            ]
        }

        let availability = UserAvailability(trainingDaysPerWeek: 6, unavailableWeekdays: [.sunday], allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 6))

        let firstProposal = ConcurrentScheduler.schedule(buildInputs(), constraints: constraints)
        let secondProposal = ConcurrentScheduler.schedule(buildInputs(), constraints: constraints)

        func signature(_ proposal: ScheduleProposal) -> [String] {
            proposal.placements
                .sorted { $0.componentLabel == $1.componentLabel ? $0.date < $1.date : $0.componentLabel < $1.componentLabel }
                .map { placement -> String in
                    let dayOffset = placement.date.timeIntervalSince1970 - proposal.window.startDate.timeIntervalSince1970
                    let sortedReasonCodes = placement.reasonCodes.sorted { $0.rawValue < $1.rawValue }
                    return "\(placement.componentLabel)|\(dayOffset)|\(sortedReasonCodes)"
                }
        }

        XCTAssertEqual(signature(firstProposal), signature(secondProposal))
        XCTAssertEqual(firstProposal.feasibility, secondProposal.feasibility)
    }

    // MARK: - Impossible mix handling

    func testInfeasibleMixNeverSilentlyDropsSessionsAndOffersResolutionOptions() throws {
        let mix = TrainingMix(kind: .selected, name: "Impossible Mix")
        context.insert(mix)
        let component = makeComponent(
            label: "Overloaded", priority: .primary,
            frequency: SessionFrequency(target: 5, minimum: 5),
            flexibility: .required,
            allowsDoubleSessionPairing: false,
            mix: mix
        )
        let sessions = (0..<5).map { makeSession("S\($0)") }

        // Only 2 usable days, doubles disallowed for this required
        // component — 5 sessions cannot possibly fit.
        let availability = UserAvailability(trainingDaysPerWeek: 2, availableWeekdays: [.monday, .tuesday], allowsDoubleSessions: false, maxSessionsPerDay: 1)
        let constraints = SchedulingConstraints(availability: availability, window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7))

        let proposal = ConcurrentScheduler.schedule([ScheduledProgramInput(component: component, sessions: sessions)], constraints: constraints)

        XCTAssertEqual(proposal.feasibility, .infeasible)
        XCTAssertEqual(proposal.placements.count, 2, "the 2 that DID fit must still be placed, not discarded")
        let conflict = try XCTUnwrap(proposal.conflicts.first)
        XCTAssertEqual(conflict.unplacedSessions.count, 3)
        // `.required` flexibility must never offer to shrink itself.
        XCTAssertFalse(conflict.resolutionOptions.contains { if case .reduceFrequency = $0 { return true }; return false })
        XCTAssertFalse(conflict.resolutionOptions.contains { if case .shortenOrMoveFlexibleSession = $0 { return true }; return false })
        // Allowing doubles or adding an available day are still valid,
        // real fixes — must be offered.
        XCTAssertTrue(conflict.resolutionOptions.contains { if case .allowDoubleSessions = $0 { return true }; return false })
        XCTAssertTrue(conflict.resolutionOptions.contains { if case .addAvailableDay = $0 { return true }; return false })
    }

