        XCTAssertFalse(feasibilityFactor.satisfied)
    }

    // MARK: - AcceptScheduleProposalUseCase persistence

    func testAcceptingAProposalReparentsSessionsAndStampsSchedulerVersion() throws {
        let ownerUserID = UUID()
        let naiveDay = Day(ownerUserID: ownerUserID, date: mondayStart())
        context.insert(naiveDay)
        let session = makeSession("S0")
        naiveDay.addSession(session)
        try context.save()

        let mix = TrainingMix(kind: .selected, name: "Mix")
        context.insert(mix)
        let component = makeComponent(label: "Strength", priority: .primary, frequency: SessionFrequency(target: 1), mix: mix)

        let targetDate = Calendar.current.date(byAdding: .day, value: 5, to: mondayStart())!
        let proposal = ScheduleProposal(
            schedulerVersion: ConcurrentScheduler.currentVersion,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7),
            placements: [SessionPlacement(session: session, componentLabel: component.label, date: targetDate, sortIndexInDay: 0, reasonCodes: [.programOrderPreserved])],
            conflicts: [],
            feasibility: .feasible
        )

        try AcceptScheduleProposalUseCase.accept(proposal, ownerUserID: ownerUserID, context: context)
        try context.save()

        XCTAssertTrue(naiveDay.sessions.isEmpty, "the naive Day must no longer hold the re-placed Session")
        XCTAssertEqual(session.day?.date, targetDate)
        XCTAssertEqual(session.schedulerVersion, ConcurrentScheduler.currentVersion)
        XCTAssertEqual(session.scheduledTime, targetDate)

        let sessionID = session.id
        let reloaded = try XCTUnwrap(freshContext().fetch(FetchDescriptor<Session>(predicate: #Predicate { $0.id == sessionID })).first)
        XCTAssertEqual(reloaded.schedulerVersion, ConcurrentScheduler.currentVersion)
        XCTAssertEqual(reloaded.day?.date, targetDate)
    }

    func testAcceptingAnInfeasibleProposalThrowsAndMutatesNothing() throws {
        let ownerUserID = UUID()
        let session = makeSession("S0")
        let naiveDay = Day(ownerUserID: ownerUserID, date: mondayStart())
        context.insert(naiveDay)
        naiveDay.addSession(session)
        try context.save()

        let proposal = ScheduleProposal(
            schedulerVersion: ConcurrentScheduler.currentVersion,
            window: SchedulingWindow(startDate: mondayStart(), numberOfDays: 7),
            placements: [],
            conflicts: [SchedulingConflict(componentLabel: "X", unplacedSessions: [], reason: "no room", resolutionOptions: [])],
            feasibility: .infeasible
        )

        XCTAssertThrowsError(try AcceptScheduleProposalUseCase.accept(proposal, ownerUserID: ownerUserID, context: context)) { error in
            XCTAssertEqual(error as? ScheduleAcceptanceError, .infeasible)
        }
        XCTAssertEqual(naiveDay.sessions.count, 1, "an infeasible proposal must never mutate the calendar")
        XCTAssertNil(session.schedulerVersion)
    }
}
